SELECT (DATE_TRUNC('DAY', "USAGE_DAY")) AS "TIME_BUCKET", SUM(BYTES_TRANSFERRED) AS "ORG_DATA_TRANSFER_BYTES" FROM (SELECT "ACCOUNT_NAME" AS ACCOUNT_NAME, "ORGANIZATION_NAME" AS ORGANIZATION_NAME, "ACCOUNT_LOCATOR" AS ACCOUNT_LOCATOR, "REGION" AS SOURCE_REGION, CAST("USAGE_DATE" AS DATE) AS USAGE_DAY, "TRANSFER_TYPE" AS TRANSFER_TYPE, "TARGET_CLOUD" AS TARGET_CLOUD, "TARGET_REGION" AS TARGET_REGION, "BYTES_TRANSFERRED" AS BYTES_TRANSFERRED FROM data_transfer_daily_history) AS base GROUP BY (DATE_TRUNC('DAY', "USAGE_DAY")) ORDER BY "ORG_DATA_TRANSFER_BYTES" DESC, "TIME_BUCKET" LIMIT 100
